def test_alert_creation_and_retrieval_across_sessions() -> None:
    """Verifies that alerts generated by RuleEngine persist to PostgreSQL and can be retrieved in a new session."""
    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()
        job_id = f"vj-alert-test-{uuid.uuid4().hex[:6]}"

        # Seed real video job in database
        async with session_factory() as session:
            job = VideoJobModel(
                id=job_id,
                filename="alert_cam.mp4",
                storage_path=f"data/uploads/{job_id}.mp4",
                file_size_bytes=500000,
                status="done",
            )
            session.add(job)
            await session.commit()

        # Trigger occupancy alert for this job
        cv_data = {
            "peak_occupancy": 30,
            "average_dwell_seconds": 20.0,
            "entries": 5,
            "unique_customers": 10,
            "total_frames": 300,
        }
        alerts = await rule_engine.evaluate_and_persist(cv_data, job_id=job_id)
        assert len(alerts) >= 1
        created_alert = alerts[0]
        assert created_alert.severity == "critical"
        assert created_alert.type == "Critical Store Occupancy"

        # Read back in a completely separate database session
        async with session_factory() as session2:
            db_alert = await session2.get(AlertModel, created_alert.id)
            assert db_alert is not None
            assert db_alert.id == created_alert.id
            assert db_alert.job_id == job_id
            assert db_alert.severity == "critical"
            assert db_alert.acknowledged is False
            assert len(db_alert.idempotency_key) == 64

    asyncio.run(_run())


def test_alert_idempotency_and_duplicate_prevention() -> None:
    """Verifies that retrying or processing the exact same event generates the same idempotency key and produces no duplicates."""
    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()
        job_id = f"vj-idem-{uuid.uuid4().hex[:6]}"

        async with session_factory() as session:
            job = VideoJobModel(
                id=job_id,
                filename="idem_test.mp4",
                storage_path=f"data/uploads/{job_id}.mp4",
                file_size_bytes=400000,
                status="done",
            )
            session.add(job)
            await session.commit()

        cv_event = {
            "peak_occupancy": 26,  # triggers critical occupancy
            "average_dwell_seconds": 10.0,
            "entries": 2,
            "unique_customers": 5,
            "total_frames": 150,
        }

        # First run
        first_res = await rule_engine.evaluate_and_persist(cv_event, job_id=job_id)
        assert len(first_res) == 1
        first_alert = first_res[0]

        # Second run with exact same telemetry (simulate task retry)
        second_res = await rule_engine.evaluate_and_persist(cv_event, job_id=job_id)
        assert len(second_res) == 1
        second_alert = second_res[0]
        assert first_alert.id == second_alert.id

        # Verify PostgreSQL contains exactly 1 alert row for this job
        async with session_factory() as s_check:
            res = await s_check.execute(
                select(AlertModel).where(AlertModel.job_id == job_id)
            )
            rows = res.scalars().all()
            assert len(rows) == 1
            assert rows[0].id == first_alert.id

    asyncio.run(_run())


def test_distinct_event_occurrences_generate_separate_alerts() -> None:
    """Verifies that separate legitimate event occurrences (e.g. distinct customer tracks or windows) generate distinct alerts."""
    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()
        job_id = f"vj-distinct-{uuid.uuid4().hex[:6]}"

        async with session_factory() as s:
            job = VideoJobModel(
                id=job_id,
                filename="multi_events.mp4",
                storage_path=f"data/uploads/{job_id}.mp4",
                file_size_bytes=300000,
                status="done",
            )
            s.add(job)
            await s.commit()

        # Telemetry with 2 distinct customers triggering individual dwell thresholds in different windows
        cv_data = {
            "peak_occupancy": 10,
            "average_dwell_seconds": 40.0,  # below global threshold
            "entries": 2,
            "unique_customers": 2,
            "total_frames": 500,
            "tracking_summaries": [
                {
                    "track_id": 101,
                    "first_frame": 10,
                    "last_frame": 250,
                    "dwell_seconds": 135.0,  # >= 120.0s threshold
                },
                {
                    "track_id": 102,
                    "first_frame": 260,
                    "last_frame": 490,
                    "dwell_seconds": 140.0,  # >= 120.0s threshold
                },
            ],
        }

        alerts = await rule_engine.evaluate_and_persist(cv_data, job_id=job_id)
        assert len(alerts) == 2
        alert_ids = {a.id for a in alerts}
        assert len(alert_ids) == 2  # Two distinct alerts for two distinct tracks

        # Verify different idempotency keys
        async with session_factory() as s_check:
            res = await s_check.execute(
                select(AlertModel).where(AlertModel.job_id == job_id)
            )
            records = res.scalars().all()
            assert len(records) == 2
            keys = {r.idempotency_key for r in records}
            assert len(keys) == 2

    asyncio.run(_run())


def test_concurrent_insertion_handling() -> None:
    """Verifies that concurrent insertions of the same alert do not fail and result in exactly one persistent record."""
    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()
        job_id = f"vj-conc-{uuid.uuid4().hex[:6]}"

        async with session_factory() as s:
            job = VideoJobModel(
                id=job_id,
                filename="concurrent_test.mp4",
                storage_path=f"data/uploads/{job_id}.mp4",
                file_size_bytes=300000,
                status="done",
            )
            s.add(job)
            await s.commit()

        cv_event = {
            "peak_occupancy": 27,
            "average_dwell_seconds": 15.0,
            "entries": 4,
            "unique_customers": 8,
            "total_frames": 200,
        }

        # Run 5 concurrent evaluate_and_persist tasks on the exact same event
        tasks = [
            rule_engine.evaluate_and_persist(cv_event, job_id=job_id)
            for _ in range(5)
        ]
        results = await asyncio.gather(*tasks)

        # All 5 return the same alert ID
        all_returned_ids = [r[0].id for r in results if r]
        assert len(set(all_returned_ids)) == 1

        # Exactly 1 row in the database
        async with session_factory() as s_check:
            db_res = await s_check.execute(
                select(AlertModel).where(AlertModel.job_id == job_id)
            )
            db_alerts = db_res.scalars().all()
            assert len(db_alerts) == 1

    asyncio.run(_run())


def test_alert_filtering_and_sorting() -> None:
    """Verifies that list_alerts correctly filters by severity, acknowledgment, and sorts newest first."""
    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()

        # Seed alerts of various severities
        cv_critical = {"peak_occupancy": 35, "job_id": f"job-crit-{uuid.uuid4().hex[:4]}"}
        cv_warning = {"peak_occupancy": 18, "job_id": f"job-warn-{uuid.uuid4().hex[:4]}"}
        cv_info = {"entries": 25, "unique_customers": 30, "job_id": f"job-info-{uuid.uuid4().hex[:4]}"}

        await rule_engine.evaluate_and_persist(cv_critical)
        await rule_engine.evaluate_and_persist(cv_warning)
        await rule_engine.evaluate_and_persist(cv_info)

        # Filter severity=critical
        crit_alerts = await rule_engine.list_alerts(severity="critical")
        assert all(a.severity == "critical" for a in crit_alerts)

        # Filter severity=warning
        warn_alerts = await rule_engine.list_alerts(severity="warning")
        assert all(a.severity == "warning" for a in warn_alerts)

        # Filter severity=info
        info_alerts = await rule_engine.list_alerts(severity="info")
        assert all(a.severity == "info" for a in info_alerts)

        # Filter acknowledged=False
        unack_alerts = await rule_engine.list_alerts(acknowledged=False)
        assert all(a.acknowledged is False for a in unack_alerts)

    asyncio.run(_run())


def test_alert_acknowledgment_persistence_across_sessions() -> None:
    """Verifies that PATCH acknowledgment and notes are committed and survive new sessions."""
    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()

        # Create alert
        cv = {"peak_occupancy": 32, "job_id": f"job-ack-{uuid.uuid4().hex[:4]}"}
        created = await rule_engine.evaluate_and_persist(cv)
        alert_id = created[0].id

        # Update in session 1
        update_req = AlertUpdateRequest(acknowledged=True, notes="Investigated by store manager")
        updated = await rule_engine.update_alert(alert_id, update_req)
        assert updated is not None
        assert updated.acknowledged is True

        # Verify in fresh independent session 2 directly from DB
        async with session_factory() as s2:
            alert_db = await s2.get(AlertModel, alert_id)
            assert alert_db is not None
            assert alert_db.acknowledged is True
            assert alert_db.notes == "Investigated by store manager"
            assert alert_db.acknowledged_at is not None

    asyncio.run(_run())


def test_api_alert_lifecycle_and_missing_alert(client: TestClient) -> None:
    """Verifies API endpoints GET /api/v1/alerts and PATCH /api/v1/alerts/{id} with PostgreSQL persistence."""
    rule_engine = get_rule_engine()
    rule_engine.evaluate_cv_results({
        "peak_occupancy": 29,
        "average_dwell_seconds": 120.0,
        "job_id": f"api-test-{uuid.uuid4().hex[:4]}",
    })

    # GET alerts
    res = client.get("/api/v1/alerts")
    assert res.status_code == 200
    data = res.json()
    validated = AlertsResponse(**data)
    assert validated.totalCount >= 1
    assert len(validated.alerts) >= 1

    target = validated.alerts[0]
    target_id = target.id

    # PATCH acknowledgment
    patch_res = client.patch(
        f"/api/v1/alerts/{target_id}",
        json={"acknowledged": True, "notes": "Confirmed on CCTV monitor 3"},
    )
    assert patch_res.status_code == 200
    patch_data = patch_res.json()
    assert patch_data["id"] == target_id
    assert patch_data["acknowledged"] is True

    # Missing alert 404
    missing_res = client.patch(
        "/api/v1/alerts/al-nonexistent-9999",
        json={"acknowledged": True},
    )
    assert missing_res.status_code == 404
    err_body = missing_res.json()
    assert "error" in err_body
    assert err_body["error"]["code"] == "RESOURCE_NOT_FOUND"


def test_database_failure_and_rollback() -> None:
    """Verifies that database failures during alert persistence trigger a rollback and do not report alerts as saved."""
    from unittest.mock import patch

    async def _run() -> None:
        rule_engine = get_rule_engine()
        session_factory = get_session_factory()
        job_id = f"vj-fail-{uuid.uuid4().hex[:6]}"

        cv_data = {
            "peak_occupancy": 35,
            "total_frames": 100,
        }

        # Mock execute to raise database error during persistence
        with patch.object(AsyncSession, "execute", side_effect=RuntimeError("Simulated PostgreSQL connection failure")):
            with pytest.raises(RuntimeError, match="Simulated PostgreSQL connection failure"):
                await rule_engine.evaluate_and_persist(cv_data, job_id=job_id)

        # Verify nothing was saved in the database
        async with session_factory() as s_check:
            res = await s_check.execute(
                select(AlertModel).where(AlertModel.job_id == job_id)
            )
            assert len(res.scalars().all()) == 0

    asyncio.run(_run())

